<script setup lang="ts">
/**
 * Wraps a control with its label, help text and error (`design/components/form-field.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/form-field.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { cloneVNode, computed, onBeforeUnmount, onMounted, useId, watch } from 'vue'

import { Icon, definedProps, removeToast, slotted, slottedElements, toast } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/form-field.module.css'

export interface FormFieldControlProps {
  id?: string
  label?: string
  invalid?: boolean
  disabled?: boolean
  'aria-describedby'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
}

export interface FormFieldProps {
  /**
   * Help text. Replaced by `error` when there is one, so they never show together.
   */
  description?: string
  /**
   * When non-empty, the field is invalid.
   */
  error?: string
  /**
   * Application errors show in toasts. The generic primitive keeps its explicit inline mode.
   */
  errorPresentation?: 'inline' | 'toast'
  /**
   * Base for the derived ids. Generated when omitted.
   */
  id?: string
  label: string
  required?: boolean
}

defineOptions({ name: 'FormField', inheritAttrs: false })

const props = withDefaults(defineProps<FormFieldProps>(), {
  errorPresentation: 'inline',
  required: false,
})
defineSlots<{
  default: (props: Record<string, never>) => unknown
  labelEnd?: (props: Record<string, never>) => unknown
}>()
const uid = useId()
const controlId = computed(() => props.id ?? uid)
const descriptionId = computed(() => `${controlId.value}-description`)
const errorId = computed(() => `${controlId.value}-error`)
const labelId = computed(() => `${controlId.value}-label`)
const invalid = computed(() => props.error !== undefined && props.error !== '')
const inline = computed(() => invalid.value && props.errorPresentation === 'inline')
const noticeId = computed(() => `${controlId.value}-notice`)
const showDescription = computed(
  () => props.description !== undefined && props.description !== '' && !invalid.value,
)
const describedBy = computed(
  () =>
    [
      inline.value ? errorId.value : undefined,
      showDescription.value ? descriptionId.value : undefined,
    ]
      .filter((value) => value !== undefined)
      .join(' ') || undefined,
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran =
    invalid.value && props.errorPresentation === 'toast'
      ? toast({
          id: noticeId.value,
          title: props.label,
          description: props.error,
          tone: 'danger',
          dismissible: true,
          retained: true,
          durationMs: Number.POSITIVE_INFINITY,
        })
      : ''
  release1 = () => {
    ran === '' || removeToast(ran)
  }
}
onMounted(effect1)
watch(() => [invalid.value, props.errorPresentation, props.error, props.label], effect1, {
  flush: 'post',
})
onBeforeUnmount(() => release1?.())
</script>

<template>
  <div
    :class="styles.field"
    :data-kind="slotted($slots.default).kind ?? 'field'"
    :data-invalid="invalid ? '' : undefined"
    :data-disabled="
      slotted($slots.default).props.disabled === true ||
      slotted($slots.default).props.disabled === ''
        ? ''
        : undefined
    "
    data-member="form-field"
  >
    <template v-if="(slotted($slots.default).kind ?? 'field') !== 'row-labelled'">
      <!-- labelRow -->
      <div :class="styles.labelRow">
        <!-- label -->
        <label
          :class="styles.label"
          :id="(slotted($slots.default).kind ?? 'field') === 'group' ? labelId : undefined"
          :for="(slotted($slots.default).kind ?? 'field') !== 'group' ? controlId : undefined"
        >
          {{ label }}
          <span v-if="required" :class="styles.required" aria-hidden="true">
            {{ ' *' }}
          </span>
        </label>
        <span v-if="$slots.labelEnd" :class="styles.labelEnd">
          <slot name="labelEnd" />
        </span>
      </div>
      <!-- description -->
      <p v-if="showDescription" :class="styles.description" :id="descriptionId">
        {{ description }}
      </p>
    </template>
    <template v-for="(node, at) in slottedElements($slots.default)" :key="at">
      <component
        :is="
          cloneVNode(
            node,
            definedProps({
              id: controlId,
              'aria-describedby': describedBy,
              'aria-required': required ? true : undefined,
              'aria-labelledby':
                (slotted($slots.default).kind ?? 'field') === 'group' ? labelId : undefined,
              invalid: invalid ? true : undefined,
              label:
                (slotted($slots.default).kind ?? 'field') === 'row-labelled' ? label : undefined,
            }),
          )
        "
      />
    </template>
    <template v-if="(slotted($slots.default).kind ?? 'field') === 'row-labelled'">
      <!-- description -->
      <p v-if="showDescription" :class="styles.description" :id="descriptionId">
        {{ description }}
      </p>
    </template>
    <!-- error -->
    <p v-if="inline" :class="styles.error" :id="errorId">
      <span :class="styles.glyph">
        <Icon name="error" size="sm" />
      </span>
      {{ error }}
    </p>
  </div>
</template>
